package device

import (
	"slices"

	"github.com/SukramJ/go-fabric/cluster/spec"
	"github.com/SukramJ/go-fabric/schema"
)

// Type is one device type as the device layer mounts it: the identity
// matter.js's MutableEndpoint carries (name, deviceType, deviceRevision,
// deviceClass) and the cluster requirements its generated device file
// states in its Requirements namespace — matter.js
// packages/node/src/devices/dimmable-light.ts:32-116 is one such file.
//
// A Type is generated by script/devicegen from parity/schema.json, one per
// device type in scope (device/<name>_gen.go). It is shared: callers must
// not modify it.
type Type struct {
	// ID is the device type id (DimmableLight 0x0101).
	ID schema.DeviceTypeID
	// Name is the device type's name as matter.js states it.
	Name string
	// Revision is the device type revision the Descriptor's DeviceTypeList
	// announces.
	Revision uint16
	// Classification is matter.js's DeviceClassification ("simple",
	// "utility", "node").
	Classification string
	// Composition is how the device type composes its PartsList.
	Composition schema.Composition
	// Base names the device type this one derives from; empty when none.
	Base string
	// Conditions are the conditions the device type declares itself.
	Conditions []string
	// Servers are the server cluster requirements, mandatory ones first,
	// each group in the order matter.js's generator emits it
	// (RequirementGenerator.ts:163-205, 207-226).
	Servers []ClusterRequirement
	// Clients are the client cluster requirements, in the same order.
	Clients []ClusterRequirement
}

// ClusterRequirement is one server or client cluster a device type
// requires or permits, as matter.js's RequirementGenerator and
// ClusterRequirements derive it (support/codegen/src/endpoints/
// RequirementGenerator.ts:141-205, ClusterRequirements.ts:65-208).
type ClusterRequirement struct {
	// ID is the cluster id.
	ID uint32
	// Name is the cluster's name.
	Name string
	// Conformance is the requirement's conformance as matter.js prints it;
	// empty when it states none.
	Conformance string
	// Mandatory is true for a cluster in matter.js's `server.mandatory`
	// (or `client.mandatory`) block: the requirement's conformance is
	// mandatory, or the Base device type mandates the server
	// (RequirementGenerator.ts:188).
	Mandatory bool
	// BaseMandated marks a server the device type does not state but the
	// Base device type mandates for it (RequirementGenerator.ts:71-106,
	// 143-155).
	BaseMandated bool
	// Features is the FeatureMap of the features the device type mandates
	// (ClusterRequirements.ts:102-117) — matter.js's `.with(...)`.
	Features uint32
	// FeatureNames are those features' codes, in requirement order.
	FeatureNames []string
	// Elements are the attribute, command and event requirements that
	// change something (ClusterRequirements.ts:137-208).
	Elements []ElementRequirement
	// Definition is the cluster's generated definition; nil for a client
	// cluster and for a cluster without one committed under cluster/spec.
	Definition *spec.Cluster
}

// Presence is what a device type's requirement does to an element's
// optionality: matter.js's alteration `optional`
// (ClusterRequirements.ts:151-163).
type Presence uint8

// Presences.
const (
	// PresenceUnchanged: the requirement leaves the element as its cluster
	// states it.
	PresenceUnchanged Presence = iota
	// PresenceMandatory: `optional: false` — RequirementDisposition.Mandate.
	PresenceMandatory
	// PresenceOptional: `optional: true` — RequirementDisposition.Relax.
	PresenceOptional
)

// ElementRequirement is an attribute, command or event requirement: the
// alteration matter.js's ClusterRequirements.ingestElement makes of it
// (ClusterRequirements.ts:137-208). Only numeric bounds and defaults are
// carried, as matter.js carries them.
type ElementRequirement struct {
	// Element is schema.RequirementAttribute, RequirementCommand or
	// RequirementEvent.
	Element schema.RequirementElement
	// Name is the element's name.
	Name string
	// ID is the attribute, command or event id.
	ID       uint32
	Presence Presence
	// Default is the element's default, where the requirement states one
	// or a constraint `value` implies it (`default ??= value`).
	HasDefault bool
	Default    float64
	// Min and Max are the constraint's bounds (a constraint `value` sets
	// both).
	HasMin bool
	Min    float64
	HasMax bool
	Max    float64
}

// Server returns the type's server requirement for clusterID.
func (t *Type) Server(clusterID uint32) (ClusterRequirement, bool) {
	i := slices.IndexFunc(t.Servers, func(r ClusterRequirement) bool { return r.ID == clusterID })
	if i < 0 {
		return ClusterRequirement{}, false
	}
	return t.Servers[i], true
}

// Element returns the requirement's element requirement of kind and id.
func (r *ClusterRequirement) Element(kind schema.RequirementElement, id uint32) (ElementRequirement, bool) {
	i := slices.IndexFunc(r.Elements, func(e ElementRequirement) bool { return e.Element == kind && e.ID == id })
	if i < 0 {
		return ElementRequirement{}, false
	}
	return r.Elements[i], true
}

// Types returns every generated device type, by id. The slice is fresh;
// the types are shared.
func Types() []*Type {
	return slices.Clone(committedTypes)
}

// TypeByID returns the generated device type id, or (nil, false).
func TypeByID(id schema.DeviceTypeID) (*Type, bool) {
	for _, t := range committedTypes {
		if t.ID == id {
			return t, true
		}
	}
	return nil, false
}

// Lookup returns the generated device type of a device type id as the
// Descriptor's DeviceTypeList carries it (a 32-bit devtype-id), or
// (nil, false) for an id device/ does not generate: an id above 0xFFFF, a
// manufacturer-specific or unknown one, and the snapshot device types
// script/devicegen excludes (its excluded list: the media client
// CastingVideoClient). It reads the generated registry (types_gen.go), so a
// regeneration that commits a type makes Lookup find it.
//
// A client view resolves a remote endpoint's device type through it, as
// matter.js's ClientStructure resolves it through the model
// (packages/node/src/node/client/ClientStructure.ts:871,
// this.#node.matter.deviceTypes(dt.deviceType)).
func Lookup(id uint32) (*Type, bool) {
	t, ok := typesByID[id]
	return t, ok
}

// typesByID indexes the generated registry for [Lookup].
var typesByID = func() map[uint32]*Type {
	m := make(map[uint32]*Type, len(committedTypes))
	for _, t := range committedTypes {
		m[uint32(t.ID)] = t
	}
	return m
}()

// typeByName returns the generated device type named name, or nil.
func typeByName(name string) *Type {
	for _, t := range committedTypes {
		if t.Name == name {
			return t
		}
	}
	return nil
}
